Random random = new Random();
int n = 100000;
int insideCircle = 0;
for (int i = 0; i < n; i++) {
    double x = random.nextDouble();
    double y = random.nextDouble();
    if (x * x + y * y <= 1) {
        insideCircle++;
    }
}
double piApprox = 4.0 * insideCircle / n;
System.out.println("Aproksymacja pi: " + piApprox);
System.out.println("Math.PI: " + Math.PI);

